import cv2
import numpy as np
import os
import time

# Path to the images directory
IMAGE_DIR = "images"

def create_directory(directory_path):
    """Creates a directory if it doesn't exist."""
    try:
        if not os.path.exists(directory_path):
            os.makedirs(directory_path)
    except OSError as e:
        print(f"Error creating directory: {e}")
        raise

def get_user_name():
    """Gets the user's name for image labeling."""
    while True:
        name = input("Enter person's name (or 'q' to quit): ").strip().lower()
        if name == 'q':
            return None
        if name:
            return name
        print("Name cannot be empty. Please try again.")

def capture_and_save_image(cap, face_cascade, name, image_count):
    """Captures a frame, detects faces, and saves them."""
    ret, frame = cap.read()
    if not ret:
        print("Failed to capture frame.")
        return False, image_count

    gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    faces = face_cascade.detectMultiScale(gray, 1.3, 5)

    for (x, y, w, h) in faces:
        cv2.rectangle(frame, (x, y), (x + w, y + h), (255, 0, 0), 2)
        face_image = gray[y:y + h, x:x + w]
        file_name = os.path.join(IMAGE_DIR, f"{name}_{image_count}.jpg")
        try:
            cv2.imwrite(file_name, face_image)
            print(f"Saved image: {file_name}")
            image_count += 1
        except OSError as e:
            print(f"Error saving image: {e}")

    cv2.imshow("Capturing Faces", frame)
    key = cv2.waitKey(1)
    if key == ord('q'):
        return False, image_count
    return True, image_count

def main():
    """Main function to capture and save face images."""
    name = get_user_name()
    if not name:
        return

    create_directory(IMAGE_DIR)

    try:
        cap = cv2.VideoCapture(0)
        if not cap.isOpened():
            raise IOError("Cannot open webcam")

        face_cascade = cv2.CascadeClassifier(cv2.data.haarcascades + 'haarcascade_frontalface_default.xml')
        if face_cascade.empty():
            raise IOError("Unable to load face cascade classifier")

        image_count = 1
        print("Starting face capture. Press 'q' to quit.")

        while image_count <= 5:
            ret, frame = cap.read()
            if not ret:
                print("Failed to capture frame. Check camera connection.")
                break

            gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            faces = face_cascade.detectMultiScale(gray, 1.3, 5)

            for (x, y, w, h) in faces:
                cv2.rectangle(frame, (x, y), (x + w, y + h), (255, 0, 0), 2)
                face_image = gray[y:y + h, x:x + w]
                file_name = os.path.join(IMAGE_DIR, f"{name}_{image_count}.jpg")
                try:
                    cv2.imwrite(file_name, face_image)
                    print(f"Saved image: {file_name}")
                    image_count += 1
                except OSError as e:
                    print(f"Error saving image: {e}")

            cv2.imshow("Capturing Faces", frame)
            key = cv2.waitKey(1)
            if key == ord('q'):
                break

    except (IOError, KeyboardInterrupt) as e:
        print(f"Exiting: {e}")
    finally:
        if 'cap' in locals():
            cap.release()
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

