import cv2
import pyzbar.pyzbar as pyzbar
import time
import datetime
import os

# Camera index for the USB QR code scanner
CAMERA_INDEX = 0

# CSV log file path
INVENTORY_LOG_PATH = "inventory_log.csv"

# Error log file path
ERROR_LOG_PATH = "error_log.txt"

def initialize_camera(camera_index):
    """Initializes the camera at the given index."""
    try:
        camera = cv2.VideoCapture(camera_index)
        if not camera.isOpened():
            raise Exception(f"Could not open camera at index {camera_index}")
        return camera
    except Exception as e:
        log_error(f"Camera initialization failed: {e}")
        return None

def capture_frame(camera):
    """Captures a single frame from the camera."""
    try:
        ret, frame = camera.read()
        if not ret:
            raise Exception("Failed to capture frame")
        return frame
    except Exception as e:
        log_error(f"Frame capture failed: {e}")
        return None

def decode_qr_code(image):
    """Decodes QR codes from a grayscale image."""
    try:
        decoded_objects = pyzbar.decode(image)
        if decoded_objects:
            return decoded_objects[0].data.decode("utf-8")
        return None
    except Exception as e:
        log_error(f"QR code decoding failed: {e}")
        return None

def validate_item_identifier(identifier):
    """Validates that the decoded identifier is alphanumeric."""
    if not identifier.isalnum():
        log_error(f"Invalid item identifier: {identifier}")
        return False
    return True

def log_inventory_item(camera_identifier, item_identifier, capture_time):
    """Logs the inventory item to the CSV log file."""
    try:
        file_exists = os.path.isfile(INVENTORY_LOG_PATH)
        with open(INVENTORY_LOG_PATH, "a") as log_file:
            if not file_exists:
                log_file.write("Camera Identifier,Item Identifier,Capture Time\n")
            log_file.write(f"{camera_identifier},{item_identifier},{capture_time}\n")
    except Exception as e:
        log_error(f"Inventory log write failed: {e}")

def log_error(message):
    """Logs an error message to the error log file."""
    timestamp = datetime.datetime.now().isoformat()
    with open(ERROR_LOG_PATH, "a") as error_file:
        error_file.write(f"{timestamp}: {message}\n")

def main():
    """Main function to run the QR code inventory system."""
    camera = initialize_camera(CAMERA_INDEX)
    if camera is None:
        print("Failed to initialize camera. Exiting.")
        return

    try:
        while True:
            frame = capture_frame(camera)
            if frame is None:
                time.sleep(0.1)
                continue

            decoded_data = decode_qr_code(frame)
            if decoded_data:
                item_identifier = decoded_data
                if validate_item_identifier(item_identifier):
                    capture_time = datetime.datetime.now().isoformat()
                    log_inventory_item("Camera 1", item_identifier, capture_time)
                    print(f"Scanned: {item_identifier} at {capture_time}")

            time.sleep(0.2)

    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        camera.release()
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

