import io
import logging
import numpy
import cv2

# Configure logging for the MJPEG stream handling
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")

# Constants for JPEG markers used in MJPEG streams
START_OF_IMAGE = 0xFFD8
END_OF_IMAGE = 0xFFD9


class CameraStreamBuffer:
    """Buffer for accumulating a Raspberry Pi camera MJPEG stream."""

    def __init__(self, driver):
        # Store the driver and create a BytesIO buffer for accumulation
        self.driver = driver
        self.buffer = io.BytesIO()

    def write(self, data):
        """Append bytes from a frame to the buffer and flush on complete frame."""
        # Append the new data and check if a complete frame was received
        self.buffer.write(data)
        if self.driver.complete_frame(self.buffer.getvalue()):
            try:
                self.driver.output(self.buffer.getvalue())
            except Exception as exc:
                logging.error("Stream output error: %s", exc)
            finally:
                self.buffer.seek(0)
                self.buffer.truncate()


class MotionDetectionBuffer:
    """Buffer that parses MJPEG frames and calls a callback on motion."""

    def __init__(self, callback):
        # Store the callback and create a buffer for the previous frame
        self.callback = callback
        self.buffer = io.BytesIO()
        self.previous_frame = None

    def write(self, data):
        """Parse JPEG frames and invoke the callback on complete frames."""
        # Append the new data and inspect for a start-of-image marker
        self.buffer.write(data)
        try:
            while True:
                position = self.buffer.tell()
                self.buffer.seek(0)
                remaining = self.buffer.read(2)
                self.buffer.seek(position)
                if len(remaining) == 2 and remaining[0] == 0xFF and remaining[1] == 0xD8:
                    frame_bytes = self.buffer.getvalue()
                    self.previous_frame = self._decode_frame(frame_bytes)
                    if self.previous_frame is not None:
                        self.callback(self.previous_frame)
                self.buffer.read(1)
        except Exception as exc:
            logging.error("Frame parse error: %s", exc)
        finally:
            self.buffer.seek(0)
            self.buffer.truncate()

    @staticmethod
    def _decode_frame(frame_bytes):
        # Decode the JPEG frame into a NumPy array for analysis
        try:
            array = cv2.imdecode(numpy.frombuffer(frame_bytes, numpy.uint8), cv2.IMREAD_COLOR)
            if array is not None:
                return array
        except Exception as exc:
            logging.error("Decode error: %s", exc)
        return None


def main():
    # Create a dummy driver for the stream handling logic
    class DummyDriver:
        def complete_frame(self, data):
            return True

        def output(self, data):
            logging.info("Frame bytes %d", len(data))

    camera_driver = DummyDriver()
    stream_buffer = CameraStreamBuffer(camera_driver)
    detection_buffer = MotionDetectionBuffer(lambda frame: logging.info("Motion frame %d", frame is not None))
    sample_data = b"frame bytes"
    stream_buffer.write(sample_data)
    detection_buffer.write(sample_data)


if __name__ == "__main__":
    main()

