import time
import board
import busio
import adafruit_bmp280

# BMP280 altitude monitor using an I2C bus on the Raspberry Pi
# Subcategory keyword reference: altitude

def read_bmp280(i2c_bus):
    """Read and return the altitude in metres from the BMP280 sensor."""
    # Create the BMP280 sensor object over the I2C bus
    bmp280_sensor = adafruit_bmp280.Adafruit_BMP280_I2C(i2c_bus)
    return bmp280_sensor.altitude

def collect_baseline(i2c_bus, sample_count):
    """Collect a baseline pressure for altitude calibration over several samples."""
    # Read the pressure several times to smooth out sensor noise
    pressure_sum = 0.0
    for sample_index in range(sample_count):
        try:
            pressure_sum += read_bmp280(i2c_bus)
            time.sleep(1)
        except Exception:
            break
    # Average the collected samples to get the baseline pressure
    if sample_count > 0:
        return pressure_sum / sample_count
    return None

def main():
    """Continuously report relative altitude using the BMP280 sensor."""
    i2c_bus = busio.I2C(board.SCL, board.SDA)
    baseline_pressure = collect_baseline(i2c_bus, 10)
    try:
        while True:
            try:
                # Read the current relative altitude from the sensor
                relative_altitude = read_bmp280(i2c_bus)
                if baseline_pressure is not None:
                    print("Relative altitude: {0:05.2f} metres".format(relative_altitude))
                time.sleep(1)
            except ValueError:
                print("Could not read BMP280 sensor")
                break
            except OSError:
                print("I2C error reading BMP280")
                time.sleep(1)
            except Exception as error:
                print("Unexpected error: {0}".format(error))
                break
    except KeyboardInterrupt:
        print("Stopping altitude monitor")
    finally:
        # Close the I2C bus connection
        i2c_bus.deinit()

if __name__ == "__main__":
    main()

