# -*- coding: utf-8 -*-
"""
Control an LED based on the state of a mechanical switch connected to an
MCP23017 I2C GPIO expander.
"""

import time
import sys
from MCP23017_I2C import GPIO_CHIP

# Constants for the switch and LED
SWITCH_PIN = 7
LED_PIN = 0
I2C_BUS = 0
POLL_INTERVAL = 0.1


def initialize_gpio(expander, switch_pin, led_pin, bus_number):
    """Initialize the GPIO pins on the MCP23017."""
    try:
        expander.setup(switch_pin, 'IN', 'PU', bus_number)
        expander.setup(led_pin, 'OUT', bus_number)
        return True
    except Exception as e:
        print(f"GPIO initialization error: {e}")
        return False


def read_switch_state(expander, switch_pin):
    """Read the state of the switch from the MCP23017."""
    try:
        return not bool(expander.input(switch_pin))
    except Exception as e:
        print(f"Error reading switch: {e}")
        return None  # Indicate an error


def update_led_state(expander, led_pin, switch_state, previous_state):
    """Update the LED state based on the switch state."""
    if switch_state is not None and switch_state != previous_state:
        state_to_set = 'HIGH' if switch_state else 'LOW'
        try:
            expander.output(led_pin, state_to_set)
            print(f"Led {'ON' if state_to_set == 'HIGH' else 'OFF'}")
            return state_to_set
        except Exception as e:
            print(f"Error setting LED: {e}")
            return previous_state  # Keep the previous state
    return previous_state


def main():
    """Main function to control the LED based on the switch."""
    switch_pin = SWITCH_PIN
    led_pin = LED_PIN
    i2c_bus = I2C_BUS

    try:
        gpio_chip = GPIO_CHIP(i2c_bus, 0x20)  # Default address, adjust if needed
        if not initialize_gpio(gpio_chip, switch_pin, led_pin, i2c_bus):
            sys.exit(1)

        previous_state = read_switch_state(gpio_chip, switch_pin)

        while True:
            current_state = read_switch_state(gpio_chip, switch_pin)
            if current_state is not None:
                previous_state = update_led_state(gpio_chip, led_pin, current_state, previous_state)
            time.sleep(POLL_INTERVAL)

    except KeyboardInterrupt:
        print("\nExiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Cleanup (if needed) -  Example: gpio_chip.cleanup() if it exists
        print("Program finished.")


if __name__ == "__main__":
    main()

