import RPi.GPIO as GPIO
import time
import signal
import sys

# Pin assignments for the three digital sensors
SENSOR_PINS = {"sensor_1": 17, "sensor_2": 27, "sensor_3": 22}
POLL_INTERVAL = 1  # seconds

def initialize_gpio():
    """Configure the GPIO pins for the digital sensors."""
    GPIO.setmode(GPIO.BCM)
    for sensor_name, sensor_pin in SENSOR_PINS.items():
        GPIO.setup(sensor_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)

def read_sensor(sensor_name):
    """Read the state of a single digital sensor."""
    try:
        sensor_pin = SENSOR_PINS[sensor_name]
        return GPIO.input(sensor_pin)
    except KeyError:
        print(f"Error: Unknown sensor '{sensor_name}'")
        return None

def report_sensor_responses():
    """Print the current state of each monitored sensor."""
    for sensor_name in SENSOR_PINS:
        sensor_state = read_sensor(sensor_name)
        if sensor_state is not None:
            print(f"Response for {sensor_name}: {'HIGH' if sensor_state else 'LOW'}")

def signal_handler(sig, frame):
    """Handle SIGINT and SIGTERM signals for graceful shutdown."""
    print("\nShutting down gracefully...")
    GPIO.cleanup()
    sys.exit(0)

def main_loop():
    """Main loop that polls the sensors and reports their states."""
    try:
        while True:
            report_sensor_responses()
            time.sleep(POLL_INTERVAL)
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        GPIO.cleanup()

if __name__ == "__main__":
    # Set up signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize GPIO pins
    initialize_gpio()

    # Start the main loop
    main_loop()

