# -*- coding: utf-8 -*-
"""
Filename: simple_dog.py
Description: A production-ready command-line interface for the DOG class,
             tailored for Raspberry Pi with comprehensive error handling,
             performance optimization, and detailed documentation.
"""

import sys
import time
import signal
import threading
import RPi.GPIO as GPIO
from DOG import DOG  # Assuming DOG class is defined in DOG.py

# Constants
SLEEP_INTERVAL = 0.1  # seconds
DEFAULT_LOG_FILE = "data.log"

# Global variables
running = True
log_file_path = DEFAULT_LOG_FILE
data_logger = None


def initialize_gpio():
    """Initializes GPIO settings. Handles potential exceptions."""
    try:
        GPIO.setmode(GPIO.BCM)
        # Add GPIO setup logic as needed (e.g., pin output, input)
    except Exception as e:
        print(f"GPIO Initialization Error: {e}", file=sys.stderr)
        sys.exit(1)


def initialize_dog():
    """Initializes the DOG object. Handles potential exceptions."""
    global data_logger
    try:
        data_logger = DOG()
        data_logger.start()  # Start the background thread if needed
    except Exception as e:
        print(f"DOG Initialization Error: {e}", file=sys.stderr)
        cleanup_resources()
        sys.exit(1)


def log_data(data):
    """Appends data to the log file. Handles potential file errors."""
    try:
        with open(log_file_path, "a") as f:
            f.write(data + "\n")
    except Exception as e:
        print(f"Logging Error: {e}", file=sys.stderr)


def receive_data_loop():
    """Continuously receives data from the DOG object and logs it."""
    global running
    while running:
        try:
            data = data_logger.receive()  # Call the receive method
            if data:  # Check if data is not empty
                log_data(data)
        except Exception as e:
            print(f"Receive Loop Error: {e}", file=sys.stderr)
            running = False  # Stop the loop on error
            break


def write_data(data):
    """Appends raw data to the log file."""
    log_data(data)


def send_data(data):
    """Sends data using the DOG object. Handles potential errors."""
    try:
        data_logger.send(data)
    except Exception as e:
        print(f"Send Error: {e}", file=sys.stderr)


def display_log():
    """Displays the contents of the log file."""
    try:
        with open(log_file_path, "r") as f:
            print(f.read())
    except FileNotFoundError:
        print(f"Log file not found: {log_file_path}", file=sys.stderr)
    except Exception as e:
        print(f"Display Error: {e}", file=sys.stderr)


def cleanup_resources():
    """Cleans up GPIO resources."""
    print("Cleaning up resources...")
    global running, data_logger
    running = False  # Ensure threads stop

    if data_logger:
        data_logger.stop() # Stop the background thread if needed
        data_logger.join() # Wait for the thread to finish

    try:
        GPIO.cleanup()
    except Exception as e:
        print(f"GPIO Cleanup Error: {e}", file=sys.stderr)


def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    print("\nExiting gracefully...")
    cleanup_resources()
    sys.exit(0)


def main():
    """Main function to run the command-line interface."""
    global log_file_path

    initialize_gpio()
    initialize_dog()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    receive_thread = threading.Thread(target=receive_data_loop)
    receive_thread.daemon = True  # Allow main thread to exit even if this is running
    receive_thread.start()

    try:
        while True:
            command = input("> ").strip()
            if not command:
                continue

            parts = command.split()
            action = parts[0].lower()

            if action == "start":
                if len(parts) == 2:
                    log_file_path = parts[1]
                    print(f"Logging to: {log_file_path}")
                else:
                    print("Usage: start <log_file_path>")
            elif action == "send":
                if len(parts) > 1:
                    send_data(" ".join(parts[1:]))
                    print(f"Sent: {' '.join(parts[1:])}")
                else:
                    print("Usage: send <data>")
            elif action == "write":
                if len(parts) > 1:
                    write_data(" ".join(parts[1:]))
                    print(f"Wrote: {' '.join(parts[1:])}")
                else:
                    print("Usage: write <data>")
            elif action == "display":
                display_log()
            elif action == "help":
                print("Available commands:")
                print("  start <log_file_path>")
                print("  send <data>")
                print("  write <data>")
                print("  display")
                print("  exit")
            elif action == "exit":
                break
            else:
                print("Unknown command.")

    finally:
        cleanup_resources()


if __name__ == "__main__":
    main()

