import zmq
import time
import json
import RPi.GPIO as GPIO
import select
import logging
import signal
import sys

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

class SubscriptionHandler:
    """
    Manages subscriptions to data streams and executes callbacks.
    """

    def __init__(self):
        """Initializes the SubscriptionHandler."""
        self.subscriptions = {}
        self.subscriber_socket = None
        self.stop_event = False

    def handle_message(self, subscriber_socket, message):
        """
        Processes incoming ZeroMQ messages.

        Args:
            subscriber_socket: The ZeroMQ subscriber socket.
            message (bytes): The received message.
        """
        try:
            if self.stop_event:
                return

            if isinstance(message, bytes):
                message_str = message.decode('utf-8')
            else:
                message_str = str(message)

            logger.debug(f"Received message: {message_str}")

            if message_str.startswith('SUBSCRIBE'):
                self._handle_subscribe(subscriber_socket, message_str)
            elif message_str.startswith('UNSUBSCRIBE'):
                self._handle_unsubscribe(subscriber_socket, message_str)
            elif message_str.startswith('PUBSUB'):
                self._handle_pubsub(subscriber_socket, message_str)
            else:
                logger.warning(f"Unknown message format: {message_str}")
                self.unsubscribe_all(subscriber_socket)  # Clean up on unknown message

        except Exception as e:
            logger.error(f"Error processing message: {e}", exc_info=True)
            self.unsubscribe_all(subscriber_socket)

    def _handle_subscribe(self, subscriber_socket, message):
        """Handles subscription requests."""
        try:
            stream_id = message.split()[1]
            if stream_id not in self.subscriptions:
                self.subscriptions[stream_id] = []
            subscriber_socket.setsockopt_string(zmq.SUBSCRIBE, stream_id)
            logger.info(f"Subscribed to stream: {stream_id}")
        except Exception as e:
            logger.error(f"Error subscribing to stream: {e}", exc_info=True)

    def _handle_unsubscribe(self, subscriber_socket, message):
        """Handles unsubscription requests."""
        try:
            stream_id = message.split()[1]
            subscriber_socket.setsockopt_string(zmq.UNSUBSCRIBE, stream_id)
            logger.info(f"Unsubscribed from stream: {stream_id}")
            if not subscriber_socket.getsockopt_string(zmq.SUBSCRIBE, 0):  # Check if no subscriptions remain
                self.unsubscribe_all(subscriber_socket)

        except Exception as e:
            logger.error(f"Error unsubscribing from stream: {e}", exc_info=True)

    def _handle_pubsub(self, subscriber_socket, message):
        """Handles PUB/SUB mode switching."""
        try:
            stream_id = message.split()[1]
            if stream_id in self.subscriptions:
                logger.info(f"Entering PUB/SUB mode for stream: {stream_id}")
                subscriber_socket.setsockopt_string(zmq.PUBSUB_MODE, stream_id)
            else:
