import RPi.GPIO as GPIO
import time
import random

# Predictive maintenance vibration trend tracking for urban monitoring
# SW-420 vibration sensor connected to GPIO17 (BCM numbering)
SENSOR_PIN = 17
SAMPLE_COUNT = 6
SAMPLE_INTERVAL = 0.3

def setup_sensor():
    """Configure the GPIO pin for the vibration sensor with a pull-up."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)

def read_vibration():
    """Read the vibration sensor and return a simulated amplitude."""
    # Simulate amplitude when vibration is detected (LOW) or idle (HIGH)
    if GPIO.input(SENSOR_PIN) == GPIO.LOW:
        return random.uniform(6.0, 9.0)
    else:
        return random.uniform(3.0, 5.0)

def main():
    """Main function to track vibration trends and recommend maintenance."""
    setup_sensor()
    try:
        # Collect samples to estimate the vibration trend
        amplitudes = [read_vibration() for _ in range(SAMPLE_COUNT)]
        average_amplitude = sum(amplitudes) / SAMPLE_COUNT
        # Predictive maintenance decision based on the average amplitude
        if average_amplitude > 7.5:
            print("Maintenance recommended: wear trend is high")
        else:
            print("Component healthy: no action needed")
    except Exception as error:
        # Handle any exceptions that might occur during sensor reading
        print(f"An error occurred: {error}")
    finally:
        # Ensure GPIO resources are released
        GPIO.cleanup()

if __name__ == "__main__":
    main()

