import smbus2
from contextlib import contextmanager

# Generic I2C device read/write helper for Raspberry Pi
# Subcategory: smbus2 I2C device access
# Context: Raspberry Pi home automation node

I2C_BUS_NUMBER = 1
DEFAULT_DEVICE_ADDRESS = 0x40


@contextmanager
def open_i2c_bus(bus_number, device_address):
    """Context manager for I2C bus resource management."""
    try:
        bus = smbus2.SMBus(bus_number)
        yield bus, device_address
    finally:
        bus.close()


def check_device_acknowledge(bus, device_address):
    """Verify the device is acknowledging on the I2C bus."""
    try:
        bus.read_byte(device_address)
    except OSError as bus_error:
        raise RuntimeError("I2C device not acknowledging at address 0x%x" % device_address) from bus_error


def write_register(bus, device_address, register, value):
    """Write a single byte to a register."""
    try:
        bus.write_byte_data(device_address, register, value)
    except OSError as bus_error:
        raise RuntimeError("Failed to write to register 0x%x value 0x%x" % (register, value)) from bus_error


def read_register(bus, device_address, register):
    """Read a single byte from a register."""
    try:
        return bus.read_byte_data(device_address, register)
    except OSError as bus_error:
        raise RuntimeError("Failed to read from register 0x%x" % register) from bus_error


class I2CDevice:
    """Generic I2C device driver wrapper."""

    def __init__(self, device_address=DEFAULT_DEVICE_ADDRESS, bus_number=I2C_BUS_NUMBER):
        """Initialize the I2C device handle."""
        self.device_address = device_address
        self.bus_number = bus_number

    def open(self):
        """Open the I2C bus and confirm the device is present."""
        with open_i2c_bus(self.bus_number, self.device_address) as (bus, _):
            check_device_acknowledge(bus, self.device_address)

    def write_register(self, register, value):
        """Write a register value via smbus2."""
        with open_i2c_bus(self.bus_number, self.device_address) as (bus, _):
            write_register(bus, self.device_address, register, value)

    def read_register(self, register):
        """Read a register value via smbus2."""
        with open_i2c_bus(self.bus_number, self.device_address) as (bus, _):
            return read_register(bus, self.device_address, register)

    def close(self):
        """No explicit close needed, managed by context manager."""
        pass


if __name__ == "__main__":
    # Example usage for a hypothetical sensor device
    sensor_device = I2CDevice(device_address=0x48, bus_number=I2C_BUS_NUMBER)
    try:
        sensor_device.open()
        sensor_device.write_register(0x01, 0x83)
        sensor_value = sensor_device.read_register(0x00)
        print("Sensor value read:", hex(sensor_value))
    except RuntimeError as device_error:
        print("I2C device error:", device_error)
    finally:
        sensor_device.close()

