import time
import smbus2
import adafruit_ccs811

# I2C configuration for the air quality sensor on the Raspberry Pi
I2C_BUS_NUMBER = 1
SENSOR_ADDRESS = 0x5A


def verify_sensor(i2c_bus):
    """Check that the CCS811 sensor is present on the I2C bus."""
    # Attempt to read the sensor’s status register
    try:
        i2c_bus.read_byte_data(SENSOR_ADDRESS, 0x00)
        return True
    except OSError:
        return False


def read_air_quality(i2c_bus):
    """Read and return the CO2 concentration in parts per million."""
    # Instantiate the Adafruit driver for the CCS811 sensor
    air_sensor = adafruit_ccs811.CCS811(i2c_bus)
    # Wait for the sensor to become ready with a short timeout
    if not air_sensor.data_ready:
        time.sleep(0.1)
    if air_sensor.data_ready:
        return air_sensor.eco2
    return None


if __name__ == "__main__":
    # Open the I2C bus that the air quality sensor is wired to
    i2c_bus = smbus2.SMBus(I2C_BUS_NUMBER)
    try:
        if verify_sensor(i2c_bus):
            # Continuously sample the air quality for a short demonstration
            for sample_index in range(5):
                co2_ppm = read_air_quality(i2c_bus)
                if co2_ppm is not None:
                    print("CO2 concentration: {0} ppm".format(co2_ppm))
                time.sleep(2)
        else:
            print("Air quality sensor not found on I2C bus")
    except (OSError, IOError) as sensor_error:
        # Handle I2C communication failures gracefully
        print("Sensor communication error: {0}".format(sensor_error))
    finally:
        # Release the I2C bus handle on exit
        i2c_bus.close()

