import smbus2
import datetime
import logging
import time
import signal
import sys

# Configure logging for the DS1338 RTC driver
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")

# I2C address of the DS1338 RTC chip
DS1338_ADDRESS = 0x68

# I2C bus number on the Raspberry Pi (bus 1)
I2C_BUS_NUMBER = 1

# Register map for the DS1338 RTC
REGISTER_SECONDS = 0x00
REGISTER_MINUTES = 0x01
REGISTER_HOURS = 0x02
REGISTER_DAY = 0x03
REGISTER_DATE = 0x04
REGISTER_MONTH = 0x05
REGISTER_YEAR = 0x06
REGISTER_CONTROL = 0x07


class DS1338Error(Exception):
    """Base class for DS1338-specific exceptions."""
    pass


class DS1338InitializationError(DS1338Error):
    """Raised when DS1338 initialization fails."""
    pass


class DS1338:
    """Driver class for the DS1338 Real-Time Clock (RTC) chip."""

    def __init__(self, bus_number=I2C_BUS_NUMBER, address=DS1338_ADDRESS):
        """Initialize the DS1338 RTC driver."""
        try:
            self.i2c_bus = smbus2.SMBus(bus_number)
        except OSError as e:
            raise DS1338InitializationError(f"Failed to initialize I2C bus: {e}")
        self.address = address

    def _read_register(self, register_address):
        """Read a byte from the specified register."""
        try:
            return self.i2c_bus.read_byte_data(self.address, register_address)
        except OSError as e:
            raise DS1338Error(f"I2C read error: {e}")

    def _write_register(self, register_address, value):
        """Write a byte to the specified register."""
        try:
            self.i2c_bus.write_byte_data(self.address, register_address, value)
        except OSError as e:
            raise DS1338Error(f"I2C write error: {e}")

    def _bcd_to_int(self, bcd_value):
        """Convert BCD to integer."""
        return int(bcd_value / 16) * 10 + int(bcd_value % 16)

    def _int_to_bcd(self, integer_value):
        """Convert integer to BCD."""
        tens_digit = int(integer_value / 10)
        ones_digit = int(integer_value % 10)
        return int(tens_digit * 16 + ones_digit)

    def _read_all_registers(self):
        """Read all 7 RTC registers."""
        try:
            registers = []
            for register in range(REGISTER_SECONDS, REGISTER_YEAR + 1):
                registers.append(self._read_register(register))
            return registers
        except DS1338Error as e:
            logging.error(f"Error reading registers: {e}")
            return None

    def read_datetime(self, century=21):
        """Read the date and time from the RTC and return a datetime object."""
        registers = self._read_all_registers()
        if registers is None:
            return None
        try:
            seconds = self._bcd_to_int(registers[REGISTER_SECONDS])
            minutes = self._bcd_to_int(registers[REGISTER_MINUTES])
            hours = self._bcd_to_int(registers[REGISTER_HOURS] & 0x3F)  # Mask 24/12h bit
            day = self._bcd_to_int(registers[REGISTER_DAY])
            date = self._bcd_to_int(registers[REGISTER_DATE])
            month = self._bcd_to_int(registers[REGISTER_MONTH])
            year = self._bcd_to_int(registers[REGISTER_YEAR]) + (century * 100)
            return datetime.datetime(year, month, date, hours, minutes, seconds)
        except ValueError as e:
            logging.error(f"Invalid date/time data: {e}")
            return None

    def write_all(self, registers):
        """Write all 7 RTC registers."""
        try:
            for offset, value in enumerate(registers):
                self._write_register(offset + REGISTER_SECONDS, value)
            return True
        except DS1338Error as e:
            logging.error(f"Error writing registers: {e}")
            return False

    def write_datetime(self, dt):
        """Write the date and time to the RTC from a datetime object."""
        try:
            registers = [
                self._int_to_bcd(dt.second),
                self._int_to_bcd(dt.minute),
                self._int_to_bcd(dt.hour),  # 24-hour format
                self._int_to_bcd(dt.isoweekday()),
                self._int_to_bcd(dt.day),
                self._int_to_bcd(dt.month),
                self._int_to_bcd(dt.year % 100),
            ]
            return self.write_all(registers)
        except ValueError as e:
            logging.error(f"Invalid datetime object: {e}")
            return False


def signal_handler(sig, frame):
    """Handle SIGINT and SIGTERM signals for graceful shutdown."""
    logging.info("Received signal, shutting down...")
    sys.exit(0)


def main():
    """Main function to demonstrate DS1338 usage."""
    ds1338 = DS1338()
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        # Verify RTC presence by reading the current time
        current_time = ds1338.read_datetime()
        if current_time:
            logging.info(f"RTC is present and time is: {current_time.isoformat()}")
        else:
            raise DS1338InitializationError("RTC not responding after initialization.")

        # Set the date and time
        new_time = datetime.datetime(2023, 10, 25, 14, 30, 0)
        if ds1338.write_datetime(new_time):
            logging.info(f"Time set to: {new_time.isoformat()}")
            # Re-read and confirm the setting
            confirmed_time = ds1338.read_datetime()
            if confirmed_time:
                logging.info(f"Time confirmed: {confirmed_time.isoformat()}")
            else:
                logging.error("Failed to re-read time after setting.")
        else:
            logging.error("Failed to set time.")

    except DS1338Error as e:
        logging.error(f"DS1338 error: {e}")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        try:
            ds1338.i2c_bus.close()
        except AttributeError:
            pass  # Handle the case where i2c_bus might not be initialized
        logging.info("Exiting program.")


if __name__ == "__main__":
    main()

