# CO2 sensor reader for Raspberry Pi Zero W
# Reads a UART CO2 sensor and logs ppm values with timestamps
import serial
import time
import os
import signal
import sys

# Configuration constants
SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
READ_TIMEOUT = 1.0
SAMPLE_INTERVAL = 5.0
LOG_FILE = "co2_readings_log.txt"


def initialize_serial(port, baud, timeout):
    """Initializes and returns a serial port object."""
    try:
        return serial.Serial(port, baud, timeout=timeout)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None


def read_co2_concentration(serial_port):
    """Reads a line from the serial port and returns the CO2 concentration as an integer."""
    try:
        line = serial_port.readline().decode("ascii", errors="replace").strip()
        if line:
            return int(line)
        return None
    except ValueError:
        print("Error: Could not decode or convert data from CO2 sensor.")
        return None
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None


def log_reading(reading, log_filepath):
    """Logs the CO2 reading with a timestamp to the specified file."""
    timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
    log_entry = f"{timestamp} - CO2: {reading} ppm\n"
    try:
        with open(log_filepath, "a") as logfile:
            logfile.write(log_entry)
    except IOError as e:
        print(f"Error writing to log file: {e}")


def main_loop(serial_port):
    """Main loop to continuously read and log CO2 data."""
    try:
        while True:
            co2_ppm = read_co2_concentration(serial_port)
            if co2_ppm is not None:
                print(f"CO2 Concentration: {co2_ppm} ppm")
                log_reading(co2_ppm, LOG_FILE)
            time.sleep(SAMPLE_INTERVAL)
    except KeyboardInterrupt:
        print("Exiting CO2 sensor reader.")
    finally:
        serial_port.close()
        print("Serial port closed.")


def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    print("Received shutdown signal. Exiting...")
    sys.exit(0)


if __name__ == "__main__":
    # Set up signal handling for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize the serial port
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, READ_TIMEOUT)

    # Start the main loop if the serial port was opened successfully
    if serial_connection:
        main_loop(serial_connection)
    else:
        print("Failed to initialize serial connection. Exiting.")

