import serial
import time
import RPi.GPIO as GPIO

# Configure serial port for the radiation sensor
SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
SERIAL_TIMEOUT = 1
ALARM_PIN = 18

def setup_gpio():
    """Configure the GPIO pin used to signal high radiation levels."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(ALARM_PIN, GPIO.OUT)
    GPIO.output(ALARM_PIN, GPIO.LOW)

def read_radiation_level(serial_connection):
    """Read a radiation level from the serial port and return it as a float."""
    try:
        line = serial_connection.readline().decode("ascii", errors="replace").strip()
        if line:
            return float(line)
        return None
    except ValueError:
        return None

def main():
    """Main function to continuously monitor radiation levels and trigger an alarm."""
    setup_gpio()
    serial_connection = None
    try:
        # Open the serial port for the radiation sensor
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=SERIAL_TIMEOUT)
        while True:
            radiation_value = read_radiation_level(serial_connection)
            if radiation_value is not None:
                print(f"Radiation Level: {radiation_value:.2f} µSv/h")
                if radiation_value > 50.0:
                    GPIO.output(ALARM_PIN, GPIO.HIGH)
                else:
                    GPIO.output(ALARM_PIN, GPIO.LOW)
            time.sleep(1)
    except serial.SerialException as serial_error:
        print(f"Serial port error: {serial_error}")
    except KeyboardInterrupt:
        print("Monitoring interrupted by user.")
    finally:
        # Ensure the serial port is closed and GPIO is cleaned up
        if serial_connection is not None and serial_connection.is_open:
            serial_connection.close()
        GPIO.cleanup()

if __name__ == "__main__":
    main()

