import pynmea2

# Configure the UART port for the GPS module
gps_port = serial.Serial("/dev/ttyUSB0", baudrate=9600, timeout=1)

# Define the log file path
log_filepath = "gps_coordinates_log.txt"


def parse_gps_data(gps_data):
    """Parses a GPS data string and returns latitude, longitude, and altitude."""
    try:
        msg = pynmea2.parse(gps_data)
        if msg._class == 'GPGGA':
            latitude = msg.latitude
            longitude = msg.longitude
            altitude = msg.altitude
            return latitude, longitude, altitude
        return None, None, None
    except pynmea2.ParseError as e:
        print(f"GPS Parse Error: {e}")
        return None, None, None


def log_coordinates(log_file, latitude, longitude, altitude):
    """Logs the GPS coordinates to a file with a timestamp."""
    timestamp = time.strftime("%Y-%m-%dT%H:%M:%S")
    log_entry = f"{timestamp}, {latitude}, {longitude}, {altitude} m\n"
    try:
        with open(log_file, "a") as file_handle:
            file_handle.write(log_entry)
    except IOError as e:
        print(f"File I/O Error: {e}")


def main():
    """Main function to read GPS data, parse it, and log the coordinates."""
    try:
        while True:
            try:
                gps_data = gps_port.readline().decode('ascii', errors='replace')
            except UnicodeDecodeError as e:
                print(f"Decoding Error: {e}")
                continue

            latitude, longitude, altitude = parse_gps_data(gps_data)

            if latitude is not None and longitude is not None and altitude is not None:
                print(f"Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude} m")
                log_coordinates(log_filepath, latitude, longitude, altitude)

            time.sleep(1)

    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        gps_port.close()
        print("GPS port closed.")


if __name__ == "__main__":
    main()

