# pulse oximeter reader for Raspberry Pi healthcare monitoring
# Reads heart rate and SpO2 from a pulse oximeter over UART
import serial
import time

def open_serial_port(device_path, baud_rate):
    """Open and configure the serial port for the pulse oximeter."""
    # Configure the serial port with standard defaults for the sensor
    serial_connection = serial.Serial(device_path, baud_rate, 8, parity='N', stopbits=1, timeout=1)
    return serial_connection

def read_pulse_oximeter(serial_connection):
    """Read a line from the serial port and decode it into heart rate and SpO2."""
    # Read a line from the serial port and decode it into a string
    raw_line = serial_connection.readline().decode('ascii', errors='replace').strip()
    if not raw_line:
        return None, None
    fields = raw_line.split(',')
    if len(fields) != 2:
        raise ValueError("Expected two comma-separated fields")
    return int(fields[0]), int(fields[1])

def main():
    """Main entry point that reads the pulse oximeter repeatedly."""
    # Open the serial port connected to the pulse oximeter
    serial_connection = open_serial_port('/dev/ttyUSB0', 9600)
    try:
        while True:
            heart_rate, spo2 = read_pulse_oximeter(serial_connection)
            if heart_rate is not None and spo2 is not None:
                print("Heart Rate: %d bpm, SpO2: %d %" % (heart_rate, spo2))
            time.sleep(1)
    except KeyboardInterrupt:
        print("Pulse oximeter monitoring stopped")
    except ValueError as read_error:
        print("Invalid data received: %s" % read_error)
    finally:
        # Always close the serial port on exit
        serial_connection.close()

if __name__ == "__main__":
    main()

