# Smart Energy Meter Reader for Raspberry Pi
# Reads power consumption from a UART meter and logs it.

import serial
import time
import os
import sys

# Configuration constants
SERIAL_PORT = "/dev/serial0"
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = "power_consumption.log"

def read_meter_data(serial_connection):
    """Reads a line of data from the serial port and returns it as a string."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        return line
    except serial.SerialException as e:
        print(f"Serial read error: {e}")
        return None

def parse_power_value(line):
    """Parses a line of text into a float representing power consumption."""
    try:
        power = float(line)
        return power
    except ValueError:
        print(f"Invalid data received: {line}")
        return None

def log_power_reading(power, log_filepath):
    """Logs the power reading to a file with a timestamp."""
    timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
    log_entry = f"{timestamp} - Power: {power} W\n"
    try:
        with open(log_filepath, "a") as log_file:
            log_file.write(log_entry)
    except IOError as e:
        print(f"Error writing to log file: {e}")

def main():
    """Main function to read and log power consumption data."""
    try:
        with serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT) as meter:
            print(f"Connected to meter on {SERIAL_PORT}")
            while True:
                line = read_meter_data(meter)
                if line:
                    power = parse_power_value(line)
                    if power is not None:
                        log_power_reading(power, LOG_FILE)
    except serial.SerialException as e:
        print(f"Could not open serial port {SERIAL_PORT}: {e}")
        sys.exit(1)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        print("Program finished.")

if __name__ == "__main__":
    main()

